import pandas as pd

def orders_with_city(orders, customers):
    """Return orders joined with their customer's city."""
    merged = orders.merge(customers, on="customer_id")
    merged = merged[["order_id", "customer_id", "city"]]
    return merged.sort_values("order_id").reset_index(drop=True)

import pandas as pd

def employee_departments(employees, departments):
    """Return employees with dept names, 'Unknown' when missing."""
    merged = employees.merge(departments, on="dept_id", how="left")
    merged["dept_name"] = merged["dept_name"].fillna("Unknown")
    return merged[["employee", "dept_id", "dept_name"]].reset_index(drop=True)
